import { sumNumericLeaves } from "./solution";

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsUnsupported(value: unknown, message: string): void {
  let error: unknown;
  try { sumNumericLeaves(value); } catch (caught) { error = caught; }
  if (!(error instanceof TypeError) || error.message !== "Unsupported value.") throw new Error(message);
}

equal(sumNumericLeaves(4.5), 4.5, "numeric leaf");
equal(sumNumericLeaves([]), 0, "empty array");
equal(sumNumericLeaves({}), 0, "empty object");
equal(sumNumericLeaves([1, { a: 2, b: [-3, 4.5] }, []]), 4.5, "nested arrays and objects");

const nullPrototype = Object.create(null) as Record<string, unknown>;
nullPrototype.first = 10;
nullPrototype.second = { nested: -2 };
equal(sumNumericLeaves(nullPrototype), 8, "null-prototype plain object");

const ordered: Record<string, unknown> = {};
ordered.first = 1e20;
ordered.second = -1e20;
ordered.third = 3;
equal(sumNumericLeaves(ordered), 3, "ordinary Object.values traversal order");

const input = { values: [1, { value: 2 }] };
const before = JSON.stringify(input);
equal(sumNumericLeaves(input), 3, "sum input");
equal(JSON.stringify(input), before, "input not mutated");

for (const unsupported of [null, "1", true, false, undefined, Symbol("x"), 1n, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY, new Date(0), /x/, new Number(2), new Map<string, number>()]) {
  throwsUnsupported(unsupported, `unsupported ${String(unsupported)}`);
}
throwsUnsupported(() => 1, "function unsupported");
throwsUnsupported([1, null, 2], "unsupported nested value");
class Custom { value = 2; }
throwsUnsupported(new Custom(), "custom prototype unsupported");

